u=Uc(UC_ARCH_X86,UC_MODE_16);u.mem_map(0,0x100000);u.mem_write(0x30000,b[0x15fc0:0x15fc0+0xefbc])
def wb(o,v):u.mem_write(0x10480+o,bytes([v]))
def ww(o,v):u.mem_write(0x10480+o,struct.pack('<H',v))
def rd(o):return struct.unpack('<H',u.mem_read(0x10480+o,2))[0]
done=False
def hook(u,a,n,z):
 global done
 if a==0xf0100:done=True;u.emu_stop()
u.hook_add(UC_HOOK_CODE,hook)
def oracle(var,mask,current,state):
 pending=0x5a;phase=0x1234
 if ((1<<(var&31))&65535)&mask:
  if current==255:current=var;phase=1 if var==2 else 2;state=1
  elif current!=var and state==0:pending=var;state=2
 return [current,pending,phase,state]
cases=0
def run(var,mask,current,state):
 global done,cases
 for o,v in [(0x4c2a,mask),(0x4c23,current),(0x4c24,0x5a)]:wb(o,v)
 ww(0x4c26,0x1234);ww(0x4c3a,state);u.mem_write(0x10480+0xd000,struct.pack('<3H',0x100,0xf000,0xab00|var))
 for reg,v in [(UC_X86_REG_CS,0x3000),(UC_X86_REG_DS,0x1048),(UC_X86_REG_SS,0x1048),(UC_X86_REG_SP,0xd000),(UC_X86_REG_BP,0xbeef),(UC_X86_REG_SI,0x2345),(UC_X86_REG_DI,0x3456)]:u.reg_write(reg,v)
 done=False;u.emu_start(0x3aae6,0,count=80);assert done
 actual=[u.mem_read(0x10480+0x4c23,1)[0],u.mem_read(0x10480+0x4c24,1)[0],rd(0x4c26),rd(0x4c3a)]
 assert actual==oracle(var,mask,current,state),(var,mask,current,state,actual)
 assert u.mem_read(0x10480+0x4c2a,1)[0]==mask and u.reg_read(UC_X86_REG_SP)==0xd004
 assert [u.reg_read(r) for r in [UC_X86_REG_BP,UC_X86_REG_SI,UC_X86_REG_DI]]==[0xbeef,0x2345,0x3456]
 cases+=1
for var,mask in itertools.product(range(256),range(256)):run(var,mask,255,0)
for var,current,state in itertools.product(range(256),range(256),[0,1,0xffff]):run(var,255,current,state)
for state in range(65536):run(1,2,0,state)
